import sys
import math

def is_perfect_square(x):
    return int(math.isqrt(x)) ** 2 == x

def find_good_permutation(n):
    if n == 1:
        return [0]

    # Try to construct the permutation
    p = [-1] * n
    used = [False] * n

    for i in range(n):
        found = False
        for j in range(n):
            if not used[j] and is_perfect_square(i + j):
                p[i] = j
                used[j] = True
                found = True
                break
        if not found:
            return [-1]

    return p

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        result = find_good_permutation(n)
        if result == [-1]:
            results.append("-1")
        else:
            results.append(" ".join(map(str, result)))

    print("\n".join(results))

if __name__ == "__main__":
    main()
